# scripts/start-local.ps1<br># This script starts the AI Personal CEO stack locally.<br># Prerequisites: Docker Desktop running, Ollama running on host (http://localhost:11434/api/tags).<br># It will copy .env.local.example to .env.local if the latter does not exist.<br># Then it runs Docker Compose, waits for health checks, and opens the browser.<br><br>function Test-DockerRunning {<br>    try { docker info > $null } catch { return $false }<br>    return $true<br>}<br><br>if (-not (Test-DockerRunning)) {<br>    Write-Host 'Docker does not appear to be running. Please start Docker Desktop and retry.' -ForegroundColor Red<br>    exit 1<br>}<br><br># Check Ollama endpoint<br>try {<br>    $resp = Invoke-WebRequest -Uri http://localhost:11434/api/tags -UseBasicParsing -TimeoutSec 5<br>    if ($resp.StatusCode -ne 200) { throw 'bad' }<br>} catch {<br>    Write-Host 'Ollama does not appear to be reachable at http://localhost:11434. Start Ollama (ollama serve) and retry.' -ForegroundColor Red<br>    exit 1<br>}<br><br># Verify model exists<br$model = (Get-Content .env.local.example | Select-String -Pattern '^OLLAMA_MODEL=').Matches[0].Value.Split('=')[1] -replace '`r`n',''<br>if (-not (ollama list | Select-String $model)) {<br>    Write-Host (Write-Host 'Model $model not found locally. Pull it now? (y/n)') -ForegroundColor Yellow<br>    $answer = Read-Host<br>    if ($answer -eq 'y') { ollama pull $model } else { Write-Host 'Please pull the model before continuing.'; exit 1 }<br>}<br><br># Copy env if needed<br>if (-not (Test-Path .env.local)) {<br>    Copy-Item .env.local.example .env.local<br>    Write-Host 'Created .env.local from example.'<br>}<br><br># Start Docker Compose<br>docker compose --env-file .env.local up -d --build<br><br># Wait for services<br$services = @('http://localhost:3000','http://localhost:8080/actuator/health','http://localhost:8000/api/v1/health')<br>foreach ($url in $services) {<br>    $ok = $false<br>    for ($i=0;$i -lt 30;$i++) {<br>        try { $r = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 3; if ($r.StatusCode -eq 200) { $ok = $true; break } } catch {}<br>        Start-Sleep -Seconds 2<br>    }<br>    if (-not $ok) { Write-Host 